&lt;b&gt;Langues&lt;/b&gt; abyssal, c&#233;leste, commun, infernal, prot&#233;en ; &lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;pathie-(Capacit&#233;).html&quot; title=&quot;T&#233;l&#233;pathie (Sur)&quot;&gt;t&#233;l&#233;pathie&lt;/a&gt; &#224; 30 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Forme-(Capacit&#233;).html&quot; title=&quot;Changement de forme (Sur)&quot;&gt;changement de forme&lt;/a&gt; (scorpion de taille TG ou &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; &#224; queue de scorpion ; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Forme.html&quot; title=&quot;Changement de forme&quot;&gt;changement de forme&lt;/a&gt;&lt;/i&gt;), prime du meurtrier
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
